	private static NativeProjectedBindingSet nativeRow(Map<String, Value> values) {
		Source source = new Source();
		String[] names = values.keySet().toArray(String[]::new);
		int[] positions = new int[names.length];
		long[] ids = new long[names.length];
		for (int i = 0; i < names.length; i++) {
			positions[i] = i;
			Value value = values.get(names[i]);
			ids[i] = value == null ? NativeLmdbQuerySource.UNKNOWN_ID : i + 1L;
			if (value != null)
				source.values.put(ids[i], value);
		}
		return new NativeProjectedBindingSet(source, names, positions, ids);
	}

